/* Плагин «СУБД» — PostgreSQL и Postgres Pro через HTTP-шлюз.
   ======================================================================
   ПОЧЕМУ ЧЕРЕЗ ШЛЮЗ. Браузер не умеет говорить по протоколу PostgreSQL: это
   свой двоичный протокол поверх TCP, а странице доступен только HTTP(S) и
   WebSocket. Значит между таблицей и базой обязан стоять кто-то, кто
   переводит: PostgREST, pgweb, Supabase, свой маленький сервис на чём
   угодно. Плагин говорит с ним по HTTP и никаких паролей от базы в себе не
   держит — их знает шлюз.

   Ожидаемый уговор со шлюзом (он же — что просить у администратора):
     GET  {сервер}/objects?схема=public   -> [{"схема","имя","вид","строк"}]
     GET  {сервер}/columns?объект=public.t -> [{"имя","тип"}]
     POST {сервер}/query  {"sql":"…","предел":N} -> {"columns":[…],"rows":[[…]]}
   Ответы — JSON. Ни одного из этих путей плагин не зашивает намертво: все
   три лежат в настройках, потому что у PostgREST они одни, у своего
   сервиса другие, и подгонять их надо без правки кода.                    */

const НЕТСЕРВЕРА = 'Не указан адрес шлюза. Заполните поле «Шлюз» в панели.';

function п(){ return параметры({}); }
function корень(о){ return String(о.сервер || хранилище.взять('шлюз', '')).replace(/\/+$/, ''); }
/* Токен — из поля панели, а если его там нет, из хранилища: поле пароля в
   книгу не уходит, а работать после перезапуска надо. */
function токен(о){ return о.токен || хранилище.взять('токен', ''); }

/* ---- доступ помнится ВНЕ КНИГИ -------------------------------------------
   Адрес шлюза и токен — про этого человека и его браузер, а не про книгу:
   книга ходит по рукам, токен ходить не должен. Поэтому они в хранилище
   плагина: «тайно» — значит не уйдёт и в выгруженный файл плагина. */
function Запомнить(){
  const о = п();
  if(!корень(о)) throw new Error(НЕТСЕРВЕРА);
  хранилище.положить('шлюз', корень(о));
  хранилище.положить('схема', о.схема || 'public');
  if(о.токен) хранилище.тайно('токен', о.токен);
  сообщить('Доступ запомнен в этом браузере: ' + корень(о)
    + (о.токен ? ' и токен (в книгу и в файл плагина он не уходит)' : ''));
}
function Забыть(){
  хранилище.очистить();
  сообщить('Запомненный доступ убран.');
}
/* При запуске плагина — подставить запомненное в поля панели. */
function Вспомнить(){
  const шлюз = хранилище.взять('шлюз', ''), схема = хранилище.взять('схема', '');
  if(шлюз) панель.поле('сервер', шлюз);
  if(схема) панель.поле('схема', схема);
  if(шлюз) сообщить('Шлюз из памяти: ' + шлюз + (хранилище.взять('токен') ? ', токен на месте' : ''));
}

async function взять(о, путь, тело){
  if(!корень(о)) throw new Error(НЕТСЕРВЕРА);
  const заг = {'Content-Type': 'application/json'};
  if(токен(о)) заг['Authorization'] = 'Bearer ' + токен(о);
  const ответ = await запрос(корень(о) + путь, тело
    ? {метод: 'POST', заголовки: заг, тело: JSON.stringify(тело)}
    : {метод: 'GET', заголовки: заг});
  if(!ответ.ок) throw new Error('Шлюз ответил ' + ответ.код + ': ' + String(ответ.текст || '').slice(0, 300));
  if(ответ.тело === null || ответ.тело === undefined)
    throw new Error('Шлюз вернул не JSON. Первые знаки: ' + String(ответ.текст || '').slice(0, 120));
  return ответ.тело;
}

/* Список таблиц и представлений — в дерево панели: схема становится папкой. */
async function Объекты(){
  const о = п();
  const путь = (о.путьОбъектов || '/objects') + '?схема=' + encodeURIComponent(о.схема || 'public');
  const список = await взять(о, путь);
  if(!Array.isArray(список)) throw new Error('Ожидался массив объектов, пришло другое.');
  панель.дерево('объекты', список.map(function(x){
    const схема = x.схема || x.schema || 'public';
    const имя = x.имя || x.name || '?';
    const вид = x.вид || x.type || 'table';
    return {имя: имя + (вид === 'view' ? '  (представление)' : ''), путь: схема + '/' + имя};
  }));
  панель.сообщение('Объектов: ' + список.length + '. Выберите и нажмите «Столбцы» или «Загрузить».');
  сообщить('Объектов:', список.length);
}

async function Столбцы(){
  const о = п();
  const цель = String(о.объекты || '').replace('/', '.');
  if(!цель){ панель.сообщение('Сначала выберите объект в дереве.'); return; }
  const список = await взять(о, (о.путьСтолбцов || '/columns') + '?объект=' + encodeURIComponent(цель));
  панель.список('столбцы', (список || []).map(function(c){
    return (c.имя || c.name) + ' : ' + (c.тип || c.type || '?');
  }));
  панель.сообщение(цель + ' — столбцов: ' + (список || []).length);
}

/* Выполнить запрос и налить результат на лист, начиная с текущей клетки. */
async function Загрузить(){
  const о = п();
  const цель = String(о.объекты || '').replace('/', '.');
  const предел = Math.max(1, Math.min(1000000, parseInt(о.предел, 10) || 10000));
  const sql = (о.запрос && о.запрос.trim())
    ? о.запрос.trim()
    : (цель ? 'select * from ' + цель : '');
  if(!sql){ панель.сообщение('Нечего выполнять: выберите объект или напишите запрос.'); return; }
  сообщить('Запрос:', sql);
  const r = await взять(о, о.путьЗапроса || '/query', {sql: sql, предел: предел});
  const колонки = r.columns || r.столбцы || [];
  const строки = r.rows || r.строки || [];
  if(!строки.length){ панель.сообщение('Запрос вернул ноль строк.'); return; }

  const где = книга.выделение || {лист: книга.листы[0], строка: 1, столбец: 1};
  const л = лист(где.лист);
  const r0 = где.строка, c0 = где.столбец;

  /* Шапка — имена столбцов, под ней строки. Пишем по строке за раз: на
     сотне тысяч строк поклеточная запись стоит на порядок дороже. */
  л.диапазон(бук(c0) + r0 + ':' + бук(c0 + колонки.length - 1) + r0)
   .записать([колонки.map(function(x){ return typeof x === 'string' ? x : (x.имя || x.name); })]);
  for(let i = 0; i < строки.length; i++)
    л.диапазон(бук(c0) + (r0 + 1 + i) + ':' + бук(c0 + колонки.length - 1) + (r0 + 1 + i))
     .записать([строки[i]]);

  /* Помечаем разметку: шапка отчёта — строка имён, числа — всё под ней.
     Не закрываем: это выгрузка таблицы, а не отчёт по измерениям, и
     проваливаться тут некуда. */
  л.разметка({шапка: бук(c0) + r0 + ':' + бук(c0 + колонки.length - 1) + r0,
              данные: бук(c0) + (r0 + 1) + ':' + бук(c0 + колонки.length - 1) + (r0 + строки.length),
              боковик: '', закрыто: false});
  панель.сообщение('Загружено строк: ' + строки.length + ', столбцов: ' + колонки.length + '.');
  сообщить('Загружено строк:', строки.length);
}

/* Проверка связи: самый дешёвый запрос, какой умеет любой шлюз. */
async function Проверить(){
  const о = п();
  try {
    const r = await взять(о, о.путьЗапроса || '/query', {sql: 'select 1 as ок', предел: 1});
    const ок = (r.rows || r.строки || [])[0];
    панель.сообщение(ок ? 'Связь есть, шлюз отвечает.' : 'Шлюз ответил, но без строк — проверьте путь запроса.');
  } catch(e){
    панель.сообщение('Не вышло: ' + e.message);
  }
}

/* Номер столбца в буквы: 1 -> A, 27 -> AA. Своя, потому что у плагина нет
   доступа к внутренностям таблицы. */
function бук(n){
  let s = '';
  while(n > 0){ const o = (n - 1) % 26; s = String.fromCharCode(65 + o) + s; n = (n - 1 - o) / 26; }
  return s;
}
